/// Result of a syscall: the value, or the [`Errno`] the guest receives negated.
pub type SyscallResult<T = Slong> = Result<T, Errno>;

impl Errno {
    /// Encodes the error as a raw syscall return value (`-errno`).
    pub const fn to_ret(self) -> Slong {
        self.0.wrapping_neg()
    }
    /// Decodes a raw syscall return value: `Some` for Linux's error range `-4095..=-1`.
    pub fn from_ret(ret: Slong) -> Option<Self> {
        if (-4095..=-1).contains(&ret) {
            Some(Self(-ret))
        } else {
            None
        }
    }
}

